static void check(bool value,const char* why){if(!value)throw std::runtime_error(why);}
int main(){try{
 check(sliceRound(-1.5)==-1&&sliceRound(1.5)==2,"JS Math.round negative tie");
 check(sanitizeSliceName(U"  a/b:*?  ")==U"ab","Slice filename sanitization");
 auto normalized=normalizeDocumentSlices({{" a ",U"",{-1,20,99,99}},{"a",U"duplicate",{0,0,1,1}},{"bad",U"bad",{0,0,0,2}}},10,8);check(normalized.size()==1&&normalized[0].id=="a"&&normalized[0].name==U"Slice 1"&&normalized[0].rect==SliceRect{0,7,10,1},"Normalize rejects duplicate/invalid and clamps");
 auto moved=moveSliceRects({{1,2,2,2},{5,3,2,3}},9,-9,10,8);check(moved[0]==SliceRect{4,0,2,2}&&moved[1]==SliceRect{8,1,2,3},"Group move common clamp preserves offsets");
 check(autoSliceCount(10,8,{3,2,1,1,1,0})==6&&autoSliceRects(10,8,{3,2,1,1,1,0}).size()==6,"Grid slice count with gaps/start");check(autoSliceRects(1024,1024,{1,1,0,0,0,0}).empty(),"10000 auto slice admission cap");
 Document d(8,6);d.markSaved();const auto pixels=d.pixels();const auto content=d.contentRevision();check(d.createSlices({{1,1,3,2},{5,2,2,3}}),"Create slices");check(d.dirty()&&d.historySize()==1&&d.contentRevision()==content&&d.pixels()==pixels,"Metadata history leaves raster/cache revision unchanged");auto before=d.slices();const auto first=before[0].id,second=before[1].id;check(d.selectedSliceIds().size()==2,"Create multiselection");d.selectSlice(first);d.selectSlice(second,true);check(d.selectedSliceId()==second,"Primary follows last selected");d.selectSlice(first,true);check(d.selectedSliceIds()==std::vector<std::string>{second},"Shift deselection");d.selectAllSlices();auto target=d.slices();target[0].rect.x=2;target[1].rect.x=6;const auto h=d.historySize();check(d.updateSlices(target)&&d.historySize()==h+1,"Group move one transaction");d.undo();check(d.slices()==before&&d.selectedSliceIds().size()==2,"Undo restores geometry and selection");d.redo();check(d.slices()[0].rect.x==2,"Redo group move");auto source=d.slices()[0];check(d.duplicateSlices({source})&&d.slices().size()==3&&d.slices().back().name==source.name&&d.slices().back().id!=source.id,"Alt copy preserves name but unique identity");const auto copy=d.selectedSliceId();check(d.deleteSlices({copy})&&d.slices().size()==2,"Delete selected");d.undo();check(d.selectedSliceId()==copy&&d.slices().size()==3,"Delete undo restores selected ID");auto rename=d.slices()[0];rename.name=U"  ab/c:*?  ";d.updateSlices({rename});check(d.slices()[0].name==U"abc","Rename sanitization");const auto noOp=d.historySize();d.updateSlices({d.slices()[0]});check(d.historySize()==noOp,"No-op creates no history");
 DocumentSnapshot snapshot(d);while(!snapshot.advance(d,std::chrono::steady_clock::now()+std::chrono::seconds(1))){}auto copied=snapshot.finish();check(copied.slices()==d.slices(),"Save snapshot retains slices");auto encoded=project::encodeEditableProject(copied);auto manifest=project::readProjectManifest(encoded.bytes);auto imported=project::prepareEditableImport(manifest);check(imported.slices==d.slices(),"Project save/open retains slices");auto recovery=project::encodeRecoveryProject(copied);check(project::readProjectManifest(recovery.bytes).slices==d.slices(),"Recovery retains slices");
 Document raster(8,6);raster.beginStroke({2,2},0xff123456);raster.commitStroke();raster.createSlices({{1,1,3,2}});const auto sliceId=raster.slices()[0].id;StaticImageExportOptions image;image.sliceId=sliceId;const auto stableHistory=raster.historySize();const auto stableRevision=raster.revision();auto png=encodeStaticImagePng(raster,image);check(png.width==3&&png.height==2&&png.pixels[4]==0xff123456,"PNG exports actual slice crop");check(encodeStaticImageBmp(raster,image).width==3&&encodeStaticImageIco(raster,image).height==2&&encodeStaticImageSvg(raster,image).width==3&&encodeStaticImageJpeg(raster,image).height==2,"All static formats use slice region");GifExportOptions gif;gif.sliceId=sliceId;auto animation=prepareAnimationExport(raster,gif);check(animation.width==3&&animation.height==2&&animation.frames[0][4]==0xff123456,"Animated crop shared with GIF/WebP");SpriteSheetOptions sheet;sheet.sliceId=sliceId;auto atlas=buildSpriteSheetImage(raster,sheet);check(atlas.width==3&&atlas.height==2,"Sprite sheet source uses slice rectangle");check(raster.historySize()==stableHistory&&raster.revision()==stableRevision,"Export never mutates source");image.sliceId="missing";bool missing=false;try{encodeStaticImagePng(raster,image);}catch(const std::invalid_argument&){missing=true;}check(missing,"Missing slice never silently exports canvas");
 raster.setImportedSlices({{"s1",U"Name",{0,0,1,1}},{"s2",U"name",{1,1,1,1}},{"s3",U"Name",{2,2,1,1}}});auto plan=planSliceExport(raster,{},std::filesystem::path{},U".png",[](const auto&,const auto&){return ExportConflictChoice::Cancel;});check(plan&&plan->paths.size()==3&&plan->paths[0].filename()==std::filesystem::path(U"Name.png")&&plan->paths[1].filename()==std::filesystem::path(U"name-2.png")&&plan->paths[2].filename()==std::filesystem::path(U"Name-3.png"),"Slice filenames case-insensitive duplicate suffix; no document prefix");
 std::cout<<"Slice model/history/snapshot/project/recovery/export/source checks passed\n";return 0;
 }catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
